-- All synthetic identities exist only in the disposable local database.
CREATE FUNCTION fixture_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; RAISE NOTICE 'PASS: %',label; END $$;
SELECT set_config('test.role','service_role',false);
DO $$
DECLARE u uuid:=gen_random_uuid();u2 uuid:=gen_random_uuid();actor uuid:=gen_random_uuid();other_user uuid:=gen_random_uuid();l uuid;i uuid;c uuid;c2 uuid;c3 uuid;ctl uuid;ev integer;f integer;r jsonb;n integer;
BEGIN
 INSERT INTO unidades(id,nome) VALUES(u,'FIXTURE A'),(u2,'FIXTURE B');
 INSERT INTO user_unidades VALUES(actor,u),(other_user,u2);
 INSERT INTO experimental_ciclos_config(unidade_id,ativo,crm_integrado,evochat_integrado,telegram_integrado,escritores_integrados,aprovado_em) VALUES(u,true,true,true,true,true,now());
 INSERT INTO leads(unidade_id,hora_aula_experimental) VALUES(u,'08:00') RETURNING id INTO l;
 INSERT INTO interacoes(lead_id,unidade_id,agendou_experimental,data_experimental,hora_experimental) VALUES(l,u,true,current_date,'09:00') RETURNING id INTO i;
 PERFORM fixture_assert((SELECT compareceu=false FROM interacoes WHERE id=i),'default false stays historical, no evidence created');
 PERFORM fixture_assert((SELECT count(*)=0 FROM experimental_ciclos),'no automatic backfill');
 c:=experimental_novo_ciclo(i,current_date,'09:00',actor,'crm_manual','create-1');
 PERFORM fixture_assert((SELECT compareceu IS NULL AND hora_experimental='09:00' FROM interacoes WHERE id=i),'new pending cycle overrides false explicitly and preserves intended time');
 PERFORM fixture_assert((SELECT resultado='pendente' FROM experimental_ciclos WHERE id=c),'new experimental pending');
 PERFORM fixture_assert(experimental_novo_ciclo(i,current_date,'09:00',actor,'crm_manual','create-1')=c,'creation retry idempotent');
 SELECT count(*) INTO ev FROM experimental_ciclo_eventos;
 UPDATE interacoes SET descricao='unrelated edit' WHERE id=i;
 PERFORM fixture_assert((SELECT count(*)=ev FROM experimental_ciclo_eventos),'editing without presence creates no confirmation');
 BEGIN PERFORM experimental_confirmar(c,'compareceu',other_user,'crm_manual','forbidden',0); RAISE EXCEPTION 'unexpected authorization'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='unexpected authorization' THEN RAISE; END IF; END;
 PERFORM fixture_assert((SELECT resultado='pendente' FROM experimental_ciclos WHERE id=c),'cross unit authorization denied');
 r:=experimental_confirmar(c,'compareceu',actor,'crm_manual','present-1',0);
 PERFORM fixture_assert((SELECT resultado='compareceu' AND versao=1 FROM experimental_ciclos WHERE id=c),'manual presence explicit');
 PERFORM fixture_assert((SELECT compareceu=true AND compareceu_em IS NOT NULL FROM interacoes WHERE id=i),'legacy presence projection synchronized');
 SELECT count(*) INTO f FROM follow_ups WHERE lead_id=l;
 PERFORM fixture_assert(f=4,'presence generates exactly existing D1 D7 D15 D30');
 r:=experimental_confirmar(c,'compareceu',actor,'crm_manual','present-1',0);
 PERFORM fixture_assert(r->>'repetido'='true' AND (SELECT count(*)=f FROM follow_ups WHERE lead_id=l),'repeated presence never duplicates follow ups');
 BEGIN PERFORM experimental_confirmar(c,'nao_compareceu',actor,'crm_manual','correction-no-reason',1); RAISE EXCEPTION 'unexpected correction'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='unexpected correction' THEN RAISE; END IF; END;
 PERFORM fixture_assert((SELECT resultado='compareceu' FROM experimental_ciclos WHERE id=c),'contradictory result requires explicit correction');
 r:=experimental_confirmar(c,'nao_compareceu',actor,'crm_manual','correct-1',1,'explicit fixture correction');
 PERFORM fixture_assert((SELECT count(*)=1 FROM experimental_ciclo_eventos WHERE ciclo_id=c AND tipo='corrigido' AND resultado_anterior='compareceu' AND resultado_novo='nao_compareceu' AND responsavel_id=actor),'manual correction preserves before after actor');
 PERFORM fixture_assert((SELECT bool_and(status='cancelado') FROM follow_ups WHERE lead_id=l),'legacy undo cancels pending follow ups without restart');
 PERFORM fixture_assert((SELECT estado='bloqueado' FROM experimental_ciclo_avisos WHERE ciclo_id=c),'no recipient means blocked internal notice, not invented target');
 c2:=experimental_encerrar(c,actor,'crm_manual','rebook-1','new slot',current_date+1,'10:00');
 PERFORM fixture_assert((SELECT situacao='substituido' AND resultado='nao_compareceu' AND hora_aula='09:00' FROM experimental_ciclos WHERE id=c),'previous absence and slot preserved after rebooking');
 PERFORM fixture_assert((SELECT ciclo_anterior_id=c AND resultado='pendente' AND hora_aula='10:00' FROM experimental_ciclos WHERE id=c2),'successor links previous and starts pending');
 PERFORM fixture_assert((SELECT compareceu IS NULL AND hora_experimental='10:00' FROM interacoes WHERE id=i),'rebooking projection null and intended time');
 BEGIN PERFORM experimental_confirmar(c,'compareceu',actor,'crm_manual','old-slot',2,'old'); RAISE EXCEPTION 'unexpected old'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='unexpected old' THEN RAISE; END IF; END;
 PERFORM fixture_assert((SELECT resultado='pendente' FROM experimental_ciclos WHERE id=c2),'old cycle cannot confirm successor');
 INSERT INTO telegram_groups(unidade_id,telegram_chat_id,status,group_type) VALUES(u,-999,'conectado','comercial');
 INSERT INTO experimental_presenca_telegram(interacao_id,lead_id,unidade_id,data_aula,hora_aula,ciclo_id,status,telegram_chat_id,telegram_message_id) VALUES(i,l,u,current_date+1,'10:00',c2,'enviado',-999,10) RETURNING id INTO ctl;
 INSERT INTO cronograma_funcionarios(unidade_id,user_id,setor) VALUES(u,actor,'recepcao');
 UPDATE experimental_ciclos_config SET avisos_ativos=true,recepcao_usuario_id=actor WHERE unidade_id=u;
 r:=experimental_confirmar(c2,'nao_compareceu',NULL,'telegram','telegram-1',0,NULL,ctl,-999,10,123);
 PERFORM fixture_assert((SELECT resultado='nao_compareceu' AND respondido_por='123' FROM experimental_presenca_telegram WHERE id=ctl),'Telegram response and actual identity committed together');
 PERFORM fixture_assert((SELECT count(*)=1 FROM ops_notificacoes WHERE usuario_id=actor),'internal OPS notice once to verified reception account');
 r:=experimental_confirmar(c2,'nao_compareceu',NULL,'telegram','telegram-1',0,NULL,ctl,-999,10,123);
 PERFORM fixture_assert((SELECT count(*)=1 FROM ops_notificacoes WHERE usuario_id=actor),'repeated callback no duplicate notice');
 BEGIN PERFORM experimental_confirmar(c2,'compareceu',NULL,'telegram','wrong-message',1,NULL,ctl,-999,11,123); RAISE EXCEPTION 'unexpected message'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='unexpected message' THEN RAISE; END IF; END;
 PERFORM fixture_assert((SELECT resultado='nao_compareceu' FROM experimental_ciclos WHERE id=c2),'wrong message cannot change result');
 c3:=experimental_encerrar(c2,actor,'crm_manual','rebook-2','return to same time',current_date,'09:00');
 PERFORM fixture_assert(c3<>c AND (SELECT hora_aula='09:00' AND resultado='pendente' FROM experimental_ciclos WHERE id=c3),'return to same original time creates different UUID');
 PERFORM experimental_confirmar(c3,'compareceu',actor,'crm_manual','new-present',0);
 PERFORM fixture_assert((SELECT count(*)=4 AND bool_and(status='cancelado') FROM follow_ups WHERE lead_id=l),'new presence does not revive cancelled legacy FU or duplicate identity');
 PERFORM experimental_encerrar(c3,actor,'crm_manual','cancel','incorrect scheduling');
 PERFORM fixture_assert((SELECT situacao='cancelado' AND resultado='compareceu' FROM experimental_ciclos WHERE id=c3),'operational cancellation preserves confirmed result');
 PERFORM fixture_assert((SELECT cancelado=true AND agendou_experimental=false FROM interacoes WHERE id=i),'incorrect appointment inactivated operationally');
 BEGIN DELETE FROM interacoes WHERE id=i; RAISE EXCEPTION 'unexpected delete'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='unexpected delete' THEN RAISE; END IF; END;
 PERFORM fixture_assert((SELECT count(*)=3 FROM experimental_ciclos WHERE interacao_id=i),'deletion cannot erase cycle evidence');
 BEGIN UPDATE experimental_ciclo_eventos SET motivo='overwrite' WHERE ciclo_id=c; RAISE EXCEPTION 'unexpected evidence'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='unexpected evidence' THEN RAISE; END IF; END;
 PERFORM fixture_assert((SELECT motivo='explicit fixture correction' FROM experimental_ciclo_eventos WHERE chave='correct-1'),'append-only evidence rejects overwrite');
 BEGIN UPDATE interacoes SET compareceu=false WHERE id=i; RAISE EXCEPTION 'unexpected direct'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='unexpected direct' THEN RAISE; END IF; END;
 PERFORM fixture_assert((SELECT compareceu=true FROM interacoes WHERE id=i),'direct protected mutation blocked');
 PERFORM fixture_assert((SELECT count(*)=0 FROM experimental_ciclo_contexto),'transaction context always cleaned');
 PERFORM fixture_assert(NOT has_function_privilege('authenticated','experimental_confirmar(uuid,text,uuid,text,text,integer,text,uuid,bigint,bigint,bigint)','EXECUTE'),'manual browser cannot impersonate service RPC');
 PERFORM fixture_assert((SELECT count(*)=19 FROM pg_trigger WHERE tgrelid='interacoes'::regclass AND NOT tgisinternal AND tgname<>'zzz_experimental_interacao_guard'),'all 19 installed triggers retained');
END $$;